def longestPalindromeSubseq(s: str) -> int:
    n = len(s)
    a = [ord(ch) - 97 for ch in s]
    NONE = 26                      # "no outer character yet"
    zero = [0] * 27                # shared all-zero row for empty intervals
    # dp[i][j][c]: best good palindrome in s[i..j] whose outermost char != c
    dp = [[zero] * (n + 1) for _ in range(n + 1)]

    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            up = dp[i + 1][j]
            left = dp[i][j - 1]
            row = [0] * 27
            if a[i] == a[j]:
                take = dp[i + 1][j - 1][a[i]] + 2
                for c in range(27):
                    row[c] = take if c != a[i] else max(up[c], left[c])
            else:
                for c in range(27):
                    row[c] = max(up[c], left[c])
            dp[i][j] = row

    return dp[0][n - 1][NONE] if n > 1 else 0
